<?php if($item['status']==='accepted'):?><form method="post" action="/admin/model-agency/assignments/<?= $escape($item['id']) ?>/confirm"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><button class="button" type="submit">Confirm assignment</button></form><?php endif;?>
